/**
 * Computes the Interview Readiness Score: a transparent, weighted average
 * of measurable inputs. Deliberately NOT generated by an AI model — every
 * number here traces back to something the user actually entered.
 *
 * Configurable weights (tune here, nowhere else):
 */
const WEIGHTS = {
  technical: 0.3,
  communication: 0.2,
  confidence: 0.15,
  roleCoverage: 0.2,
  trend: 0.15,
};

const SKILL_COVERAGE_THRESHOLD = 60; // a skill counts as "covered" at this level or above
const PENALTY_PER_UNRESOLVED_PATTERN = 5;
const MAX_TOTAL_PENALTY = 15;
const MIN_INTERVIEWS_FOR_TREND = 2;

const { ROLE_SKILL_REQUIREMENTS } = require('../config/roleSkillRequirements');
const { SKILL_CATALOG } = require('../config/constants');

const performanceToScore = (rating) => ((rating - 1) / 4) * 100; // 1..5 -> 0..100

function average(numbers) {
  if (numbers.length === 0) return null;
  return numbers.reduce((a, b) => a + b, 0) / numbers.length;
}

/** Blends a skill-tracking value and an interview-performance value when
 * both exist; falls back to whichever one is actually available. */
function blend(a, b) {
  if (a === null && b === null) return null;
  if (a === null) return b;
  if (b === null) return a;
  return (a + b) / 2;
}

function computeTechnicalReadiness(skillLevels, interviews) {
  const technicalSkillLevels = SKILL_CATALOG.technical.map((name) => skillLevels[name]).filter((v) => v !== null && v !== undefined);
  const skillAvg = average(technicalSkillLevels);
  const interviewAvg = average(interviews.map((iv) => performanceToScore(iv.technicalPerformance)));
  return blend(skillAvg, interviewAvg);
}

function computeCommunicationReadiness(skillLevels, interviews) {
  const skillLevel = skillLevels.Communication ?? null;
  const interviewAvg = average(interviews.map((iv) => performanceToScore(iv.communicationPerformance)));
  return blend(skillLevel, interviewAvg);
}

function computeConfidenceReadiness(skillLevels, interviews) {
  const skillLevel = skillLevels.Confidence ?? null;
  const interviewAvg = average(interviews.map((iv) => performanceToScore(iv.confidenceLevel)));
  return blend(skillLevel, interviewAvg);
}

function computeRoleSkillCoverage(targetRole, skillLevels) {
  const requiredSkills = ROLE_SKILL_REQUIREMENTS[targetRole] || SKILL_CATALOG.technical; // sensible fallback
  const coveredCount = requiredSkills.filter((name) => (skillLevels[name] ?? 0) >= SKILL_COVERAGE_THRESHOLD).length;
  return (coveredCount / requiredSkills.length) * 100;
}

/** Centered at 50 (no change). Above 50 = improving, below = declining.
 * Requires at least MIN_INTERVIEWS_FOR_TREND interviews to mean anything. */
function computeImprovementTrend(interviews) {
  if (interviews.length < MIN_INTERVIEWS_FOR_TREND) return null;

  const sorted = [...interviews].sort((a, b) => new Date(a.date) - new Date(b.date));
  const midpoint = Math.floor(sorted.length / 2);
  const olderHalf = sorted.slice(0, midpoint);
  const recentHalf = sorted.slice(midpoint);

  const overallScore = (iv) =>
    average(
      [iv.technicalPerformance, iv.communicationPerformance, iv.confidenceLevel, iv.projectExplanationPerformance].map(
        performanceToScore
      )
    );

  const olderAvg = average(olderHalf.map(overallScore));
  const recentAvg = average(recentHalf.map(overallScore));
  if (olderAvg === null || recentAvg === null) return null;

  const delta = recentAvg - olderAvg;
  return Math.max(0, Math.min(100, 50 + delta));
}

/**
 * Combines whichever components have real data into a weighted average,
 * renormalizing weights across only the AVAILABLE components rather than
 * defaulting missing ones to 0 or 50 — a user who hasn't filled in their
 * profile yet shouldn't have their score artificially deflated by that,
 * and a fabricated default would violate "no hardcoded percentages".
 */
function combineWeighted(components) {
  const available = components.filter((c) => c.value !== null);
  if (available.length === 0) return null;

  const totalWeight = available.reduce((sum, c) => sum + c.weight, 0);
  const weightedSum = available.reduce((sum, c) => sum + c.value * c.weight, 0);
  return weightedSum / totalWeight;
}

/**
 * @param {string|undefined} targetRole - from the user's profile
 * @param {Object} skillLevels - { [skillName]: number|null }
 * @param {Array} interviews - full interview records
 * @param {Array} patterns - current Pattern documents for this user
 */
function computeReadinessScore({ targetRole, skillLevels, interviews, patterns }) {
  if (interviews.length === 0) {
    return {
      score: null,
      breakdown: null,
      reasons: [
        'Log at least one interview experience to calculate a readiness score.',
        skillLevels && Object.values(skillLevels).every((v) => v === null)
          ? 'Rate your preparation skills for a more accurate score.'
          : null,
      ].filter(Boolean),
    };
  }

  const technical = computeTechnicalReadiness(skillLevels, interviews);
  const communication = computeCommunicationReadiness(skillLevels, interviews);
  const confidence = computeConfidenceReadiness(skillLevels, interviews);
  const roleCoverage = targetRole ? computeRoleSkillCoverage(targetRole, skillLevels) : null;
  const trend = computeImprovementTrend(interviews);

  const components = [
    { key: 'technical', label: 'Technical readiness', value: technical, weight: WEIGHTS.technical },
    { key: 'communication', label: 'Communication', value: communication, weight: WEIGHTS.communication },
    { key: 'confidence', label: 'Confidence', value: confidence, weight: WEIGHTS.confidence },
    { key: 'roleCoverage', label: 'Role skill coverage', value: roleCoverage, weight: WEIGHTS.roleCoverage },
    { key: 'trend', label: 'Improvement trend', value: trend, weight: WEIGHTS.trend },
  ];

  const rawScore = combineWeighted(components);
  if (rawScore === null) {
    return { score: null, breakdown: null, reasons: ['Not enough data yet to calculate a readiness score.'] };
  }

  // Penalize unresolved recurring patterns — but NOT ones already improving
  // (trend: "decreasing"), since penalizing an issue the user is actively
  // fixing would contradict the "keep going" message they're also seeing.
  const unresolvedPatternCount = patterns.filter((p) => p.trend === 'increasing' || p.trend === 'stable').length;
  const penalty = Math.min(unresolvedPatternCount * PENALTY_PER_UNRESOLVED_PATTERN, MAX_TOTAL_PENALTY);

  const finalScore = Math.max(0, Math.min(100, rawScore - penalty));

  return {
    score: Math.round(finalScore),
    breakdown: components.map((c) => ({
      key: c.key,
      label: c.label,
      value: c.value === null ? null : Math.round(c.value),
      weight: c.weight,
      available: c.value !== null,
    })),
    penalty,
    reasons: !targetRole ? ['Add a target role to your profile for a more precise role-fit score.'] : [],
  };
}

module.exports = { computeReadinessScore, WEIGHTS };
